export function evaluate({inputs,time}){
const u=inputs.launchSpeed,g=inputs.gravity,m=inputs.mass;
const T=2*u/g,ta=u/g;
const t=sdk.clamp(time,0,T);
const v=u-g*t,y=u*t-g*t*t/2;
const ah=u*u/(2*g);
let s;
if(t<=0)s='Ready to toss';else if(t>=T-1e-9)s='Back at launch height';else if(Math.abs(t-ta)<0.005)s='At the top';else s=t<ta?'Rising':'Falling';
const F=m*g;
const o=[];
o.push(...sdk.panel({id:'lane.motion',x:10,y:34,w:300,h:370,title:'The motion',state:s}));
const ry=380,rt=80,sc=(ry-rt)/2.2;
o.push(sdk.axis('axis.h',{x:60,y:ry,length:300,orientation:'y',min:0,max:2.2,ticks:[0,0.5,1,1.5,2],label:'Height',unit:'m'}));
const by=ry-y*sc;
o.push(sdk.circle('ball.toss',160,by,24));
o.push(...sdk.vector('vec.v',{x:160,y:by},{value:v,direction:'up'},{scale:14,label:'v',role:'observed'}));
o.push(...sdk.vector('vec.a',{x:195,y:by},{value:-g,direction:'up'},{scale:6,label:'a',role:'warning'}));
o.push(...sdk.callout(215,by-40<60?60:by-40,['v '+sdk.format(v,2)+' m/s','a '+sdk.format(-g,1)+' m/s²','F '+sdk.format(F,1)+' N'],{id:'callout.toss'}));
const pts=[];
for(let i=0;i<=12;i++){const tt=Math.min(t,T)*i/12;pts.push({x:tt,y:u-g*tt});}
if(pts.length<2)pts.push({x:0,y:u});
o.push(sdk.plot('plot.vt',{x:330,y:40,w:300,h:340,axes:{x:{label:'t',min:0,max:1.8,unit:'s'},y:{label:'v',min:-5.5,max:5.5,unit:'m/s'}},series:[{label:'v',kind:'line',points:pts}]}));
return{frame:{width:640,height:420,objects:o,readouts:[{id:'velocity',value:v},{id:'acceleration',value:-g},{id:'force',value:F},{id:'motionState',value:s}]},quantities:{launchSpeed:u,gravity:g,mass:m,apexTime:ta,apexHeight:ah,height:y,velocity:v,acceleration:-g,force:F}};}
